   "id": "zbd99dfe8",
   "sez": "dibattito",
   "titolo": "Milano, manifestazione contro la violenza con Cgil, Pd e sindaco Sala",
   "orig": "Milano: Cgil, Pd, Sala domani in piazza",
   "lead": "A Milano è in programma per oggi un presidio davanti a Palazzo Marino, organizzato da Cgil insieme ad Anpi, Arci e altre associazioni, con la partecipazione del sindaco Beppe Sala. Alla manifestazione, definita statica e con servizio d'ordine del sindacato, aderiscono forze del centrosinistra, da Azione a Rifondazione Comunista. Lo slogan scelto è \"Milano non vuole la violenza\".",
   "more": [
    "Le manifestazioni di piazza contro episodi di violenza sono spesso promosse da sindacati e associazioni civili per esprimere solidarietà e chiedere maggiore sicurezza, senza necessariamente indicare un singolo evento scatenante nelle fonti disponibili."
   ],
