   "id": "z94a605a1",
   "sez": "salute",
   "titolo": "Al Bambino Gesù apre il primo ambulatorio pediatrico italiano dedicato alla miopia",
   "orig": "Al Bambino Gesù apre il primo ambulatorio pediatrico in Italia dedicato alla miopia",
   "lead": "L'ospedale pediatrico Bambino Gesù ha aperto il primo ambulatorio in Italia dedicato specificamente alla miopia nei bambini e adolescenti. Il servizio nasce in risposta all'aumento dei casi di difficoltà visiva da lontano tra i più giovani e offrirà trattamenti per contenere la progressione del disturbo, riducendo il rischio di complicanze nell'età adulta. Lo riferisce Vatican News.",
   "more": [
    "La miopia infantile è in crescita a livello globale, complice anche l'aumento del tempo passato davanti a schermi e la riduzione delle attività all'aperto. Diagnosi precoce e trattamenti specifici possono ridurre il rischio di complicazioni oculari più gravi in età adulta."
   ],
