   "id": "z5b96c218",
   "sez": "cultura",
   "titolo": "Il direttore del museo nazionale coreano si dimette per un'opera attribuita erroneamente",
   "orig": "(3rd LD) National museum chief resigns over misattributed work from private collection",
   "lead": "You Hong-june, direttore del Museo nazionale della Corea, si è dimesso dopo che un'opera proveniente da una collezione privata è stata attribuita erroneamente. L'episodio ha coinvolto l'autenticità di un'opera esposta nell'istituzione. Lo riferisce Yonhap.",
   "more": [
    "I musei nazionali sono custodi della credibilità scientifica delle collezioni che esibiscono: errori di attribuzione possono minare la fiducia pubblica e portare a conseguenze dirette sulla dirigenza, come dimissioni o indagini interne."
   ],
