   "sez": "economia",
   "titolo": "Bank of Cyprus completa l'acquisizione di prestiti e depositi da CDB per 570 milioni di euro",
   "orig": "Bank of Cyprus completes €570m loan and deposit acquisition from CDB",
   "lead": "Bank of Cyprus ha completato l'acquisizione di prestiti performanti per circa 130 milioni di euro e depositi per circa 440 milioni di euro dalla Cyprus Development Bank (CDB), dopo aver ottenuto tutte le necessarie approvazioni regolamentari. L'operazione, concordata nel marzo 2026, riguarda la quasi totalità dei prestiti performanti e dei depositi di CDB. Lo riferisce Cyprus Mail.",
   "more": [
    "Le acquisizioni di portafogli di prestiti e depositi tra banche sono operazioni comuni nel settore finanziario per consolidare quote di mercato o rafforzare bilanci. Richiedono l'approvazione delle autorità di vigilanza bancaria, che verificano la solidità patrimoniale e la tutela dei depositanti coinvolti nella transazione."
   ],
