   "id": "zb7ca857c",
   "sez": "cultura",
   "titolo": "A Bumthang le scuole si sfidano per far rivivere il teatro tradizionale",
   "orig": "Bumthang schools compete to revive theatrical tradition",
   "lead": "Quattro scuole della regione di Bumthang, in Bhutan, hanno partecipato a una competizione teatrale organizzata dal Wangduechhoeling Palace Museum and Cultural Centre, con l'obiettivo di stimolare la creatività degli studenti, rafforzarne la fiducia in sé stessi e preservare la cultura bhutanese. Ogni scuola ha presentato uno spettacolo di 30 minuti incentrato su temi diversi, molti dei quali legati a tradizioni e cultura locali, in un momento in cui le rappresentazioni teatrali scolastiche stanno diventando sempre più rare nel paese. Lo riferisce Bhutan Broadcasting Service.",
   "more": [
    "Il Bhutan è noto per politiche culturali che puntano a preservare tradizioni e identità nazionale anche attraverso l'educazione scolastica, in un contesto di modernizzazione che rischia di erodere pratiche culturali locali come il teatro tradizionale legato a feste e cerimonie religiose."
   ],
