   "id": "zcd1acdd6",
   "sez": "viaggi",
   "titolo": "Booking.com punta a sviluppare un proprio sistema di pagamenti in India",
   "orig": "Booking.com Looks to Compete in India With Its Own Payments System and Business Travel",
   "lead": "Booking.com sta lavorando per espandere la propria presenza in India non limitandosi alle prenotazioni alberghiere ma puntando anche su un sistema di pagamenti proprio e sul segmento dei viaggi d'affari. La piattaforma punta a ottenere una quota maggiore della spesa turistica complessiva degli utenti indiani, ma dovrà confrontarsi con la concorrenza delle piattaforme locali già radicate nel settore. Lo riferisce Skift.",
   "more": [
    "Il mercato indiano dei viaggi online è in forte crescita e vede la presenza di operatori locali consolidati come MakeMyTrip, che competono con le grandi piattaforme internazionali; i pagamenti digitali in India sono dominati da sistemi locali come UPI, rendendo complesso l'ingresso di soluzioni di pagamento straniere."
   ],
