   "id": "z7051a196",
   "sez": "mondo",
   "titolo": "Carney in visita in Turchia per rilanciare i rapporti con un alleato NATO strategico",
   "orig": "Carney’s Turkish balancing act must include business, defence and human rights",
   "lead": "Il primo ministro canadese Mark Carney si reca in Turchia per rafforzare i legami commerciali, energetici e di difesa con il paese, alleato strategico della NATO. La visita, storica, segna un'inversione di rotta nei rapporti tra i due paesi, in passato compromessi da un embargo canadese sulle armi verso Ankara. Il viaggio pone a Carney la sfida di conciliare il pragmatismo economico con i valori canadesi, in un contesto segnato dalla repressione turca del dissenso interno. Lo riferisce CBC News.",
   "more": [
    "I rapporti tra Canada e Turchia si erano deteriorati dopo l'imposizione di un embargo canadese sulle forniture militari ad Ankara, legato a preoccupazioni sull'uso di componenti canadesi in operazioni militari turche; la Turchia resta comunque un alleato chiave della NATO per la sua posizione geografica strategica tra Europa, Medio Oriente e Asia."
   ],
