   "titolo": "Il fondatore di Wise: l'intelligenza artificiale raggiungerà ogni settore",
   "orig": "Wise founder: AI will eventually reach every sector",
   "lead": "L'imprenditore e investitore Taavet Hinrikus, fondatore della società di pagamenti Wise, ha dichiarato che il settore industriale estone potrebbe usare l'intelligenza artificiale e le tecnologie informatiche per migliorare una produttività attualmente relativamente bassa. Secondo Hinrikus, l'IA è destinata a diffondersi progressivamente in tutti i settori economici. Lo riferisce ERR News.",
   "more": [
    "L'Estonia è considerata uno dei paesi più digitalizzati d'Europa, con servizi pubblici quasi interamente online, ma il suo settore industriale tradizionale mostra livelli di produttività inferiori rispetto ad altri paesi europei, un divario che secondo diversi analisti potrebbe essere colmato attraverso l'adozione di tecnologie digitali avanzate."
   ],
